"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["33307"],{29283(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>l,frontMatter:()=>d,contentTitle:()=>p,toc:()=>c,assets:()=>h});var n=JSON.parse('{"id":"nhcx/v1/api/preauth/endpoints/preauth-internal-v1-preauth-on-submit","title":"Pre-authorisation callback (internal) (adapter)","description":"Internal twin of /v1/preauth/on_submit (operationId preauthOnSubmitPostInternal) with the same JWEPayload body and response set. Exposed for the NHCX adapter de","source":"@site/docs/nhcx/v1/api/preauth/endpoints/preauth-internal-v1-preauth-on-submit.mdx","sourceDirName":"nhcx/v1/api/preauth/endpoints","slug":"/nhcx/v1/api/preauth/endpoints/preauth-internal-v1-preauth-on-submit","permalink":"/docs/pr-10/docs/nhcx/v1/api/preauth/endpoints/preauth-internal-v1-preauth-on-submit","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Pre-authorisation callback (internal) (adapter)","sidebar_label":"Pre-authorisation callback (internal) (adapter)","sidebar_class_name":"api-method api-method--post","description":"Internal twin of /v1/preauth/on_submit (operationId preauthOnSubmitPostInternal) with the same JWEPayload body and response set. Exposed for the NHCX adapter de","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-preauth.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Pre-authorisation submit (internal) (adapter)","permalink":"/docs/pr-10/docs/nhcx/v1/api/preauth/endpoints/preauth-internal-v1-preauth-submit"},"next":{"title":"Receive pre-authorisation submit","permalink":"/docs/pr-10/docs/nhcx/v1/api/preauth/endpoints/preauth-webhook-v1-preauth-submit"}}'),r=a(62540),i=a(43023),o=a(70862),s=JSON.parse('{"id":"preauth_internal_v1_preauth_on_submit","module":"Pre-authorisation","moduleId":"preauth","kind":"operation","method":"POST","path":"/internal/v1/preauth/on_submit","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."}],"summary":"Pre-authorisation callback (internal) (adapter)","description":"Internal twin of /v1/preauth/on_submit (operationId preauthOnSubmitPostInternal) with the same JWEPayload body and response set. Exposed for the NHCX adapter deployment rather than for direct integration.\\n\\n### Business purpose\\n\\nThe preauth service publishes its on_submit operation twice, at /v1 and at /internal/v1, with identical descriptions, request bodies and response sets. Only the operationId differs, by an Internal suffix. The /internal prefix is the route the NHCX adapter sits on: a participant running the adapter alongside its own system calls the internal path, and the adapter handles the encryption, headers and gateway hop. A participant integrating directly against NHCX calls the public path and does that work itself. No separate business purpose is documented for the internal route beyond that.\\n\\n### When to use\\n\\nUse it only when you are running the NHCX adapter and it is configured to serve this path; otherwise call /v1/preauth/on_submit. Everything else is unchanged: the same JWEPayload body, the same x-hcx-* protected header, the same workflow discriminators and the same asynchronous callback. The specs do not document what makes the internal variant different beyond the operationId, so treat it as a mirror of the public path and confirm with NHCX onboarding before pointing production at it.\\n\\n### Preconditions\\n\\nIdentical to /v1/preauth/on_submit. Nothing additional is documented for the internal route, beyond an adapter deployment that actually serves the /internal prefix.\\n\\n### Postconditions\\n\\nHTTP 202 Accepted with the StatusSuccessResponse acknowledgement (entity_type preauth) from NHCX, then asynchronous delivery to the provider\'s registered /v1/preauth/on_submit. The provider must acknowledge with 202 within 30 seconds; otherwise NHCX retries, and after five failures the request is deleted and the sender is notified via v1/error. On an approved or partially approved response the provider persists preAuthRef and may treat; on a query the conversation stays open awaiting 19, 131 or 121; on a rejection the preauth is closed and a new case number is needed to proceed.\\n\\n### Common mistakes\\n\\n- Assuming a different body or different semantics for the internal route; the spec gives it the same JWEPayload body and the same responses.\\n- Calling it without an adapter deployment behind it and then chasing a 404.\\n- Every pitfall of the public path applies unchanged.\\n\\n### Best practices\\n\\n- Default to /v1/preauth/on_submit and keep the internal path as a configuration option only.\\n- Share one client implementation across both paths, so header hygiene, encryption and correlation handling cannot diverge between them.\\n- Record which variant carried each correlation ID, for support conversations.\\n\\n### Related scenario\\n\\nA vendor reading the preauth OpenAPI document sees preauthOnSubmitPostInternal sitting beside its public twin and asks which one to build against. The answer is the public path, unless NHCX onboarding has given them an adapter deployment, in which case the adapter takes the bundle unencrypted on the internal path and does the JWE and the gateway hop for them. The end-to-end flow is identical either way.\\n\\n### Specification\\n\\nChapter [Preauthorisation response](/docs/nhcx/v1/reference/fhir/preauthorisation-response) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"},{"name":"x-hcx-sender_code","required":true,"description":"Your participant code. Mandatory on the envelope.","example":"1518@hcx","type":"string"},{"name":"x-hcx-recipient_code","required":true,"description":"The recipient\'s. For a provider, the processor code from the policy lookup. Mandatory on the envelope.","example":"1000004446@hcx","type":"string"},{"name":"x-hcx-api_call_id","required":true,"description":"Fresh on every message, including responses. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-request_id","required":false,"description":"One per originating request. The Open Protocol page marks it Mandatory; the Technical Specifications page marks it Optional. Optional on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-correlation_id","required":true,"description":"The thread. See the rule below. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-workflow_id","required":false,"description":"Which step, or which case. See the two readings below. Optional on the envelope.","example":"21","type":"string"},{"name":"x-hcx-timestamp","required":true,"description":"See the format note below. Mandatory on the envelope.","example":"<iso timestamp>","type":"string"},{"name":"x-hcx-status","required":true,"description":"Where this message stands. Values below. Mandatory on the envelope.","example":"response.complete","type":"string"},{"name":"x-hcx-ben-abha-id","required":true,"description":"The beneficiary\'s ABHA number. Mandatory on every exchange, including those with no beneficiary in the payload. Mandatory on the envelope.","example":"91711234567890","type":"string"},{"name":"x-hcx-debug_flag","required":false,"description":"`Error`, `Info` or `Debug`. A server may ignore it. Optional on the envelope.","example":"INFO","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"payload","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"payload":"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag"},"responses":[{"status":"202","description":"HTTP 202 Accepted with the StatusSuccessResponse acknowledgement (entity_type preauth) from NHCX, then asynchronous delivery to the provider\'s registered /v1/preauth/on_submit.","example":{"timestamp":"19/03/2026 11:46:35:120","api_call_id":"a1b2c3d4-e5f6-7890-abcd-ef1234567890","correlation_id":"11223344-5566-7788-99aa-bbccddeeff00","result":{"sender_code":"1518@hcx","recipient_code":"1000004446@hcx","entity_type":"preauth","protocol_status":"request.dispatched"},"error":{"code":"","message":""}}}],"tag":"Adapter","tagDescription":"Exposed for the NHCX adapter deployment rather than for direct integration.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/internal/v1/preauth/on_submit \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'x-hcx-sender_code: 1518@hcx\' \\\\\\n  --header \'x-hcx-recipient_code: 1000004446@hcx\' \\\\\\n  --header \'x-hcx-api_call_id: <uuid>\' \\\\\\n  --header \'x-hcx-request_id: <uuid>\' \\\\\\n  --header \'x-hcx-correlation_id: <uuid>\' \\\\\\n  --header \'x-hcx-workflow_id: 21\' \\\\\\n  --header \'x-hcx-timestamp: <iso timestamp>\' \\\\\\n  --header \'x-hcx-status: response.complete\' \\\\\\n  --header \'x-hcx-ben-abha-id: 91711234567890\' \\\\\\n  --header \'x-hcx-debug_flag: INFO\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n}\'"}');let d={title:"Pre-authorisation callback (internal) (adapter)",sidebar_label:"Pre-authorisation callback (internal) (adapter)",sidebar_class_name:"api-method api-method--post",description:"Internal twin of /v1/preauth/on_submit (operationId preauthOnSubmitPostInternal) with the same JWEPayload body and response set. Exposed for the NHCX adapter de",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-preauth.yaml",generated:!0},p,h={},c=[];function u(e){return(0,r.jsx)(o.A,{operation:s})}function l(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(u,{...e})}):u(e)}}}]);